Translate("ptBR", "hana-zua", {
	title = "Hana'zua",
	subtitle = "Caçador Ferido dos Lançanegra",
	found = "O platô ao sul d'O Covil",
	hint = "Encontre o troll ferido que jaz no platô ao sul d'O Covil.",
	allegiance = "Trolls Lançanegra",
	sections = {
		{
			title = "Resumo",
			text = [=[Hana'zua é um jovem troll que foi caçar escorpídeos no {link:valley-of-trials}Vale das Provações{/link} e encontrou um muito maior que os demais. Acertou a fera com um golpe pesado na pinça, mas o ferrão dela cortou fundo seu peito. Ele jaz ferido no platô, fraco demais para voltar a pé até O Covil, e mais preocupado com sua honra do que com sua ferida. Se tiver de morrer, quer ao menos saber que seu inimigo morreu primeiro.]=],
		},
		{
			title = "Importância",
			text = [=[Hana'zua mostra o orgulho dos {link:darkspear-trolls}Lançanegra{/link}. Pede ajuda não para salvar a vida, mas para ver seu inimigo morto.]=],
		},
