Translate("ptBR", "daelin-proudmoore", {
	title = "Daelin Proudmoore",
	subtitle = "Grão-almirante de Kul Tiraz",
	allegiance = "Kul Tiraz · Casa Proudmoore",
	aliases = { "Daelin", "Almirante Proudmoore" },
	sections = {
		{
			title = "Resumo",
			text = [=[Daelin Proudmoore foi o Lorde Almirante de {link:kul-tiras}Kul Tiraz{/link} e o pai de {link:jaina-proudmoore}Jaina Proudmoore{/link}. Na {link:second-war}Segunda Guerra{/link}, suas frotas dominaram os mares pela {link:alliance}Aliança{/link}, e ele se tornou um dos grandes heróis da humanidade. Nunca perdoou os orcs por aquela guerra. Quando soube que eles haviam se estabelecido nas costas de {link:kalimdor}Kalimdor{/link}, veio com uma armada para destruí-los, e morreu na tentativa.]=],
		},
		{
			title = "Importância",
			text = [=[A guerra de Daelin foi a primeira grande ameaça à jovem nação de {link:durotar}Durotar{/link}. Sua morte traçou uma linha entre pai e filha, e entre dois modos de ver os orcs: como um povo que podia mudar, ou como monstros que nunca mudariam. Seus homens ainda ocupam a {link:tiragarde-keep}Bastilha Tiragarde{/link} em seu nome.]=],
		},
		{
			title = "O Almirante da Aliança",
			text = [=[{link:kul-tiras}Kul Tiraz{/link} era um reino de marinheiros, e a casa Proudmoore comandava suas frotas. Quando a {link:horde}Horda{/link} marchou para o norte depois da {link:first-war}Primeira Guerra{/link}, Daelin levou sua marinha à {link:alliance}Aliança{/link} de {link:lordaeron}Lordaeron{/link}. Seus navios combateram as frotas orcs em mar aberto e levaram os exércitos da Aliança de costa a costa. Kul Tiraz pagou caro em navios e homens. Daelin se lembrou desse preço pelo resto da vida.]=],
		},
		{
			title = "A Armada",
			text = [=[Depois da {link:third-war}Terceira Guerra{/link}, sua filha {link:jaina-proudmoore}Jaina{/link} conduziu os sobreviventes de {link:lordaeron}Lordaeron{/link} para o oeste, até {link:kalimdor}Kalimdor{/link}, e construiu a cidade de {link:theramore-isle}Theramore{/link}. Ali ela fez as pazes com {link:thrall}Thrall{/link}. Daelin não aceitou isso. Navegou até Kalimdor com uma grande frota, ergueu a {link:tiragarde-keep}Bastilha Tiragarde{/link} na costa de {link:durotar}Durotar{/link} e fez guerra aos orcs e aos trolls das {link:echo-isles}Ilhas do Eco{/link}. A {link:horde}Horda{/link} respondeu. Seus guerreiros quebraram a bastilha e, por fim, levaram a luta às próprias muralhas de Theramore. Jaina se afastou. Na luta, o almirante foi morto.]=],
		},
		{
			title = "Feitos",
			text = [=[• Comandou a marinha de {link:kul-tiras}Kul Tiraz{/link} na {link:second-war}Segunda Guerra{/link}.
• Ergueu a {link:tiragarde-keep}Bastilha Tiragarde{/link} nas costas de {link:durotar}Durotar{/link}.
• Fez guerra à {link:horde}Horda{/link} desafiando a paz de sua filha.
• Deixou ordens para uma guerra que continuaria depois de sua morte.]=],
		},
		{
			title = "Sem Registro",
			text = [=[Pouco está escrito aqui sobre a vida de Daelin antes das guerras. Este registro guarda apenas o que as histórias e suas próprias ordens revelam.]=],
		},
	},
	chapters = {
		{
			title = "As Ordens do Almirante",
			hint = "Leia as ordens seladas guardadas na Bastilha Tiragarde.",
			text = [=[Entre os pertences do {link:lieutenant-benedict}Tenente Benedict{/link} havia um envelope antigo com o selo do almirante. Continha ordens escritas antes mesmo de Daelin deixar {link:kul-tiras}Kul Tiraz{/link}. Mostravam que ele havia traçado bem seus planos, e que mais de seus homens deveriam seguir a primeira frota até {link:durotar}Durotar{/link}. Os orcs do {link:razor-hill}Monte Navalha{/link} leram nelas um aviso simples: o almirante estava morto, mas sua guerra não.]=],
		},
	},
	mentions = {
