			text = [=[As Ordens do Almirante, levadas a {link:gar-thok}Gar'Thok{/link}]=],
		},
		{
			text = [=[As Ordens do Almirante, levadas a {link:orgrimmar}Orgrimmar{/link}]=],
		},
	},
	bonds = {
